  component.template=component.template.replace('</header>','</header><div class="sound-map-analysis-filter"><label>歌曲标签 <select v-model="analysisTag" @change="savePreferences();rebuild(false)"><option value="">原群落颜色</option><option v-for="t in analysisTagOptions" :key="t.id" :value="t.id">{{t.label}} · {{t.count}}</option></select></label><span>{{analysisLegend}}</span></div>');
