  component.mounted=function(){const preferences=this.readPreferences?.()||{};if(typeof preferences.analysisTag==='string'&&preferences.analysisTag.length<256)this.analysisTag=preferences.analysisTag;oldMounted.call(this);if(this.active)root.FlowaveAnalysisData?.catalog(this.baseUrl).catch(()=>{});};
